import { NextResponse } from 'next/server';
import { supabaseAdmin } from '@/lib/supabase';
import { mailPage as page, confirmForm, mailToken, SITE_URL as SITE } from '@/lib/mailActionPage';

async function unsubscribe(token: string | null): Promise<boolean> {
  if (!token) return false;
  const db = supabaseAdmin();
  const { data, error } = await db
    .from('frontwire_subscribers')
    .update({ unsubscribed_at: new Date().toISOString() })
    .eq('confirm_token', token)
    .select('email')
    .maybeSingle();
  if (error) throw error;
  return !!data;
}

// ⛔ A GET MUST NEVER SUPPRESS — fixed 2026-08-13, W1.
//
// This route used to unsubscribe on GET and redirect. Corporate mail security — Microsoft
// Defender Safe Links, Proofpoint URL Defense and the rest — PREFETCHES every URL in an inbound
// message, including the one in a List-Unsubscribe header and the visible link in the footer.
// The estate has the receipt from its own cold lane: a recipient was marked contacted at
// 23:55:10.548 and an opt-out landed at 23:55:12.701, 2.1 seconds later. That is a scanner, not
// a person.
//
// Left as it was, every subscriber behind such a gateway would have been silently removed on
// DELIVERY of the first digest they were ever sent, and the list would have eroded to nothing
// with no error anywhere. This list has no subscribers yet, which is the only reason it never
// happened — it would have fired on the first real one.
//
// RFC 8058 is built around exactly this: one-click lives on POST (List-Unsubscribe-Post), which
// scanners do not issue. So GET renders a button that POSTs, and only the POST writes. Same shape
// as https://thecompound.tech/unsubscribe, which has worked this way since it shipped.
//
// The page shape and the confirm form live in @/lib/mailActionPage — the confirm route applies
// the same rule for the same reason, and one of them changing shape without the other is how the
// two ends of the same list start disagreeing about what a link in an email is allowed to do.

/** Human click on the footer link — CONFIRMS, it does not act. */
export async function GET(req: Request) {
  const token = mailToken(req);
  if (!token) {
    return page(
      "That link didn't work",
      `<p>We couldn't read that unsubscribe link — it may be incomplete or altered by your mail client.</p><p>Reply to any issue with "unsubscribe" and we'll remove you by hand.</p>`,
      400,
    );
  }
  const action = `/api/subscribe/unsubscribe?token=${encodeURIComponent(token)}`;
  return page(
    'One more click',
    `<p>Confirm you'd like to stop receiving The Front Wire.</p>` +
      confirmForm(action, 'Unsubscribe me') +
      `<p class="foot">We ask because automated mail scanners follow links in email, and we would rather not unsubscribe you by accident.</p>`,
  );
}

/** RFC 8058 one-click POST — and now also the confirm form above. */
export async function POST(req: Request) {
  const token = mailToken(req);
  try {
    const ok = await unsubscribe(token);
    // A browser posting the confirm form wants a page; an RFC 8058 client wants a bare 200.
    const wantsHtml = (req.headers.get('accept') || '').includes('text/html');
    if (!wantsHtml) return new NextResponse(null, { status: 200 });
    return ok
      ? page("You're unsubscribed", `<p>Done — no more issues. If this was a mistake, subscribe again from <a href="${SITE}">${SITE.replace(/^https?:\/\//, '')}</a>.</p>`)
      : page("That link didn't work", `<p>We couldn't match that link to a subscription. Reply to any issue with "unsubscribe" and we'll remove you by hand.</p>`, 400);
  } catch {
    const wantsHtml = (req.headers.get('accept') || '').includes('text/html');
    return wantsHtml
      ? page('That didn\'t work', '<p>Something went wrong on our side. Try again in a moment.</p>', 500)
      : new NextResponse(null, { status: 500 });
  }
}

